const ADMIN_KEY = '{{ADMIN_KEY}}';

async function grant(userId, amount) {
  const res = await fetch('/admin/grant', {
    method: 'POST',
    headers: { 'content-type': 'application/json', 'x-admin-key': ADMIN_KEY },
    body: JSON.stringify({ user_id: userId, amount }),
  });
  return res.json();
